dev-browser --headless --timeout 60 <<'EOF'
const page = await browser.getPage("main");
const errors = [];
page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });
page.on("pageerror", (err) => errors.push(String(err)));
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto("http://localhost:8737/", { waitUntil: "networkidle" });
await page.waitForTimeout(800);
let buf = await page.screenshot({ fullPage: true });
let p1 = await saveScreenshot(buf, "desktop-full.png");

await page.evaluate(() => document.querySelector('#collection').scrollIntoView());
await page.waitForTimeout(600);
buf = await page.screenshot();
let p2 = await saveScreenshot(buf, "desktop-collection.png");

await page.evaluate(() => document.querySelector('#chapters').scrollIntoView());
await page.waitForTimeout(600);
buf = await page.screenshot();
let p3 = await saveScreenshot(buf, "desktop-chapters.png");

await page.evaluate(() => document.querySelector('#threshold').scrollIntoView());
await page.waitForTimeout(600);
buf = await page.screenshot();
let p4 = await saveScreenshot(buf, "desktop-threshold.png");

console.log(JSON.stringify({ p1, p2, p3, p4, errors }, null, 2));
EOF

